// Definition for a binary tree node.
class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode(int val) { this.val = val; }
}

public boolean isValidBST(TreeNode root) {
    return validate(root, Long.MIN_VALUE, Long.MAX_VALUE);
}

private boolean validate(TreeNode node, long low, long high) {
    if (node == null) return true;                  // empty subtree is valid
    if (node.val <= low || node.val >= high) return false;  // outside inherited bounds
    return validate(node.left, low, node.val)       // left: tighten the ceiling
        && validate(node.right, node.val, high);    // right: raise the floor
}

