# Definition for a binary tree node.
class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def isValidBST(self, root: TreeNode) -> bool:
    def validate(node: TreeNode, low: float, high: float) -> bool:
        if not node:                                 # empty subtree is valid
            return True
        if not (low < node.val < high):              # outside inherited bounds
            return False
        return (validate(node.left, low, node.val)    # left: tighten the ceiling
                and validate(node.right, node.val, high))  # right: raise the floor

    return validate(root, float('-inf'), float('inf'))

