def isValidBST(self, root: TreeNode) -> bool:
    self.prev = float('-inf')

    def inorder(node: TreeNode) -> bool:
        if not node:
            return True
        if not inorder(node.left):               # check left subtree
            return False
        if node.val <= self.prev:                # not strictly increasing
            return False
        self.prev = node.val                     # remember last visited
        return inorder(node.right)               # check right subtree

    return inorder(root)

